<script>
  import {onMount,tick} from 'svelte';
  import WindowControls from './WindowControls.svelte';
  import {mapsWindow,mapsCapabilities,mapPlace,mapRoutes,mapSearch,mapDistance} from './maps-state.js';
  import {mapsMenuProvider} from './maps-commands.js';
  let {state: mapsState,profile,windowId,execute,registerView,available=true,active=true,controls={}}=$props();
  let root,mapElement,mounted=false,originalState,originalRoot,error=$state(''),openMenu=$state(''),drag=null;
  const win=$derived(mapsWindow(mapsState,windowId)),cap=$derived(mapsCapabilities(profile)),selected=$derived(mapPlace(mapsState,win?.selectedId));
  const routes=$derived(win?mapRoutes(mapsState,win):[]),route=$derived(routes.find(r=>r.key===win?.routeKey)),nodes=$derived(new Map(mapsState.nodes.map(n=>[n.id,n])));
  const visible=$derived(win?.panel==='favorites'?mapsState.favorites.map(id=>mapPlace(mapsState,id)):win?.panel==='recents'?mapsState.recents.map(r=>mapPlace(mapsState,r.placeId)):mapSearch(mapsState,win?.query??''));
  const box=$derived(win?{x:win.center.x-500/win.zoom,y:win.center.y-450/win.zoom,width:1000/win.zoom,height:900/win.zoom}:{x:0,y:0,width:1000,height:900});
  const menus=[['maps','Maps'],['file','File'],['edit','Edit'],['view','View'],['window','Window'],['help','Help']];
  function owns(){return mounted&&available&&mapsState===originalState&&root===originalRoot&&root?.isConnected&&!root.closest('[hidden],[inert]');}
  async function command(name,payload={}){if(!owns())return null;const owned=root;try{const result=await execute(`maps.${name}`,{windowId},payload);if(owns()&&owned===root)error=result?.status==='rejected'?result.message??result.error?.message??'Operation unavailable.':'';return result;}catch(cause){if(owns()&&owned===root)error=cause.message;return null;}}
  const preference=(key,value)=>command('preferences.set',{preferences:{...mapsState.preferences,[key]:value}});
  function directions(key,value){command('directions',{fromId:win.fromId??'current-location',toId:win.toId??selected?.id??mapsState.places[0]?.id,transport:win.transport,[key]:value});}
  function point(event){const rect=mapElement.getBoundingClientRect();return {x:Math.max(0,Math.min(1000,box.x+(event.clientX-rect.left)/rect.width*box.width)),y:Math.max(0,Math.min(1000,box.y+(event.clientY-rect.top)/rect.height*box.height))};}
  function pointerDown(event){if(event.button!==0||event.target.closest('[data-place]'))return;const rect=mapElement.getBoundingClientRect();drag={id:event.pointerId,x:event.clientX,y:event.clientY,center:{...win.center},width:box.width,height:box.height,rect,moved:false};mapElement.setPointerCapture(event.pointerId);}
  async function pointerUp(event){if(!drag||event.pointerId!==drag.id)return;const started=drag;drag=null;mapElement.releasePointerCapture(event.pointerId);const dx=event.clientX-started.x,dy=event.clientY-started.y;if(Math.abs(dx)+Math.abs(dy)<5)return;await command('pan',{x:Math.max(0,Math.min(1000,started.center.x-dx/started.rect.width*started.width)),y:Math.max(0,Math.min(1000,started.center.y-dy/started.rect.height*started.height))});}
  async function runMenu(row){if(!row.enabled||!row.request)return;openMenu='';const result=await execute(row.request.command,row.request.target,row.request.payload);if(owns())error=result?.status==='rejected'?result.message??'Unavailable':'';}
  async function renderDocument(source,guard){
    if(!owns()||!guard())throw new Error('The original map view changed.');
    const image=new Image(),url=URL.createObjectURL(new Blob([source.content],{type:'image/svg+xml'}));
    try{
      await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('The authored SVG map could not be decoded.'));image.src=url;});
      if(!owns()||!guard())throw new Error('The original map view changed.');
      const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=900;
      const context=canvas.getContext('2d');if(!context)throw new Error('The real map rasterizer is unavailable.');
      context.drawImage(image,0,0,1000,900);const content=canvas.toDataURL('image/png');
      canvas.width=0;canvas.height=0;
      if(!owns()||!guard())throw new Error('The original map view changed.');
      return {mime:'image/png',content};
    }finally{image.src='';URL.revokeObjectURL(url);}
  }
  onMount(()=>{mounted=true;originalState=mapsState;originalRoot=root;const facade={available:owns,renderDocument,describe:()=>({controlIds:[...root.querySelectorAll('[data-maps-control]')].filter(el=>!el.disabled&&!el.closest('[hidden],[inert]')).map(el=>el.dataset.mapsControl),scrolls:Object.fromEntries([...root.querySelectorAll('[data-maps-area]')].map(el=>[el.dataset.mapsArea,{top:el.scrollTop,left:el.scrollLeft}]))}),async focus(id,guard){await tick();const el=[...root.querySelectorAll('[data-maps-control]')].find(el=>el.dataset.mapsControl===id);if(!owns()||!guard()||!el||el.disabled||!el.getClientRects().length)return false;el.focus();return document.activeElement===el;},async scroll(id,offsets,guard){const el=[...root.querySelectorAll('[data-maps-area]')].find(el=>el.dataset.mapsArea===id);if(!owns()||!guard()||!el||!el.getClientRects().length)return null;el.scrollTo(offsets.left,offsets.top);await tick();return owns()&&guard()?{top:el.scrollTop,left:el.scrollLeft}:null;},async openMenu(id,guard){if(!owns()||!guard()||!menus.some(([key])=>key===id))return false;openMenu=id;await tick();return owns()&&guard()&&!!root.querySelector('[role="menu"]');},async closeMenu(_,guard){if(!owns()||!guard())return false;openMenu='';await tick();return owns()&&guard();}};registerView?.(windowId,facade);return()=>{mounted=false;registerView?.(windowId,null,facade);};});
</script>

<section bind:this={root} class="maps-app" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} aria-label="Maps" data-native-app="maps">
  {#if win}
    <header class="caption" data-window-drag-region>
      <WindowControls {...controls} {active} modernGreenMenu={cap.golden}/>
      {#if cap.classic}
        <button class="caption-directions" data-maps-control="directions-toolbar" data-window-no-drag class:chosen={win.panel==='directions'} onclick={()=>command('panel',{panel:win.panel==='directions'?'none':'directions'})}>Directions</button>
        <label class="toolbar-search" data-window-no-drag><span aria-hidden="true">⌕</span><input data-maps-control="search" placeholder="Search for a place or" aria-label="Search Maps" value={win.query} maxlength="4096" oninput={e=>command('search',{query:e.currentTarget.value})}/></label>
      {:else}<strong>{cap.windows?'Maps':'Harbor — Local Scene'}</strong>{/if}
      <span class="caption-tools" data-window-no-drag><button data-maps-control="location" title="Go to Current Location" onclick={()=>command('location')}>↗</button><button data-maps-control="share" title="Share" onclick={()=>command('share')}>↑</button></span>
      {#if cap.classic}<div class="toolbar-views" data-window-no-drag>{#each ['map','transit','satellite'] as mode}<button class:chosen={mode==='transit'?win.overlay==='transit':win.mode===mode&&win.overlay!=='transit'} data-maps-control={`toolbar-view:${mode}`} onclick={()=>mode==='transit'?command('overlay',{overlay:'transit'}):command('mode',{mode}).then(()=>command('overlay',{overlay:'none'}))}>{mode[0].toUpperCase()+mode.slice(1)}</button>{/each}</div>{/if}
    </header>
    <nav class="menu-bar" aria-label="Maps menus">{#each menus as [id,label]}<button data-maps-control={`menu:${id}`} aria-expanded={openMenu===id} onclick={()=>openMenu=openMenu===id?'':id}>{label}</button>{/each}</nav>
    {#if openMenu}<div class="menu" role="menu" aria-label={`${openMenu} menu`}>{#each mapsMenuProvider({state: mapsState,profile,windowId,menuId:openMenu}) as row}<button role="menuitem" disabled={!row.enabled} onclick={()=>runMenu(row)}>{row.checked?'✓ ':''}{row.label}</button>{/each}<button onclick={()=>openMenu=''}>Close Menu</button></div>{/if}
    <div class="workspace" class:modern-directions={!cap.classic&&!cap.windows&&win.panel==='directions'}>
      <aside class="sidebar" data-maps-area="sidebar">
        {#if !cap.classic}<label class="search"><span aria-hidden="true">⌕</span><input data-maps-control="search" placeholder="Search Maps" aria-label="Search Maps" value={win.query} maxlength="4096" oninput={e=>command('search',{query:e.currentTarget.value})}/></label>{/if}
        <div class="sidebar-tabs"><button data-maps-control="directions" class:chosen={win.panel==='directions'} onclick={()=>command('panel',{panel:'directions'})}>Directions</button><button data-maps-control="favorites" class:chosen={win.panel==='favorites'} onclick={()=>command('panel',{panel:'favorites'})}>Favorites</button><button data-maps-control="recents" class:chosen={win.panel==='recents'} onclick={()=>command('panel',{panel:'recents'})}>Recents</button></div>
        {#if win.panel==='directions'}
          <div class="directions-form"><label>From<select data-maps-control="from" value={win.fromId??'current-location'} onchange={e=>directions('fromId',e.currentTarget.value)}><option value="current-location">Current Location</option>{#each mapsState.places as place}<option value={place.id}>{place.name}</option>{/each}</select></label><label>To<select data-maps-control="to" value={win.toId??''} onchange={e=>directions('toId',e.currentTarget.value)}><option value="" disabled>Choose a destination</option>{#each mapsState.places as place}<option value={place.id}>{place.name}</option>{/each}</select></label><div class="transport">{#each [['drive','Drive'],['walk','Walk'],['transit','Transit']] as [id,label]}<button data-maps-control={`transport:${id}`} class:chosen={win.transport===id} onclick={()=>directions('transport',id)}>{label}</button>{/each}</div></div>
          {#if win.status}<p class="notice">{win.status}</p>{/if}
          {#each routes as choice}<button class="route-card" class:chosen={choice.key===win.routeKey} data-maps-control={`route:${choice.key}`} onclick={()=>command('route.select',{routeKey:choice.key})}><strong>{choice.minutes} min</strong><span>{mapDistance(choice.meters,mapsState.preferences.distance)} · {choice.label}</span></button>{/each}
          {#if route}<ol class="steps" data-maps-area="steps">{#each route.steps as step,i}<li><button class:chosen={win.step===i} data-maps-control={`step:${i}`} onclick={()=>command('step.select',{step:i})}>{step.text}<small>{mapDistance(step.meters,mapsState.preferences.distance)}</small></button></li>{/each}</ol><div class="document-actions"><button data-maps-control="print" onclick={()=>command('print')}>Print…</button><button onclick={()=>command('share')}>Share…</button></div>{/if}
        {:else if win.panel==='preferences'}
          <h2>{cap.settingsLabel}</h2><label>Distance<select data-maps-control="distance" value={mapsState.preferences.distance} onchange={e=>preference('distance',e.currentTarget.value)}><option value="kilometers">Kilometers</option><option value="miles">Miles</option></select></label><label><input data-maps-control="avoid-highways" type="checkbox" checked={mapsState.preferences.avoidHighways} onchange={e=>preference('avoidHighways',e.currentTarget.checked)}/>Avoid highways</label><label><input data-maps-control="avoid-tolls" type="checkbox" checked={mapsState.preferences.avoidTolls} onchange={e=>preference('avoidTolls',e.currentTarget.checked)}/>Avoid toll roads</label><label>Preferred transport<select data-maps-control="default-transport" value={mapsState.preferences.defaultTransport} onchange={e=>preference('defaultTransport',e.currentTarget.value)}><option value="drive">Driving</option><option value="walk">Walking</option><option value="transit">Transit</option></select></label>
        {:else if win.panel==='help'}<h2>Maps Help</h2><p>Search bundled Harbor places, select a pin or double-click the map to drop one. Drag to pan, scroll to zoom. Routes follow the actual authored road graph; transit follows the B1/B2 corridors.</p><p>{cap.availability}</p><p>Traffic delays and current location are fictional scene data. No location permission, live map APIs or network routing is used.</p>
        {:else}
          <h2>{win.panel==='favorites'?'Favorites':win.panel==='recents'?'Recents':win.query?'Search Results':'Harbor'}</h2>{#if !visible.length}<p class="empty">{win.query?'No local places match your search.':'No saved places.'}</p>{/if}
          {#each visible as place}<button class="place-row" class:chosen={win.selectedId===place.id} data-maps-control={`place:${place.id}`} onclick={()=>command('select',{placeId:place.id})}><span class={`place-icon ${place.category}`}>{place.category==='station'?'▣':place.category==='park'?'♧':place.category==='cafe'?'☕':'●'}</span><span><strong>{place.name}</strong><small>{place.address}</small></span></button>{/each}
          {#if win.panel==='recents'&&mapsState.recents.length}<button data-maps-control="clear-recents" onclick={()=>command('recents.clear')}>Clear Recents</button>{/if}
        {/if}
        <p class="local-label">Authored local fiction · no live maps</p>
      </aside>
      <div class="map-surface" class:satellite={win.mode==='satellite'}>
        <svg bind:this={mapElement} viewBox={`${box.x} ${box.y} ${box.width} ${box.height}`} preserveAspectRatio="none" role="img" aria-label="Interactive fictional Harbor map. Drag to pan; double-click to drop pin." onpointerdown={pointerDown} onpointerup={pointerUp} onpointercancel={()=>drag=null} onwheel={e=>{e.preventDefault();command('zoom',{zoom:Math.max(1,Math.min(8,win.zoom+(e.deltaY<0?.25:-.25)))});}} ondblclick={e=>command('pin.add',{...point(e),name:'Dropped Pin'})}>
          <defs><pattern id={`terrain-${windowId}`} width="65" height="65" patternUnits="userSpaceOnUse"><rect width="65" height="65" fill="#515c43"/><path d="M0 30L65 10M10 65L60 0" stroke="#758068" stroke-width="12"/><rect x="15" y="18" width="28" height="18" fill="#7c7968"/></pattern></defs>
          <rect x="-1000" y="-1000" width="3000" height="3000" fill={win.mode==='satellite'?`url(#terrain-${windowId})`:'#e9e7e1'}/>
          {#each mapsState.areas as area}<polygon points={area.points.map(p=>`${p.x},${p.y}`).join(' ')} fill={area.kind==='water'?(win.mode==='satellite'?'#24495f':'#abd6e8'):area.kind==='park'?(win.mode==='satellite'?'#344e31':'#c6dcad'):(win.mode==='satellite'?'#717264':'#dbd9d2')}/><text x={area.points[0].x+15} y={area.points[0].y+30} class="area-label">{area.name}</text>{/each}
          {#each mapsState.roads as road}{@const a=nodes.get(road.from)}{@const b=nodes.get(road.to)}<path d={`M${a.x} ${a.y}L${b.x} ${b.y}`} stroke={win.mode==='satellite'?'#a5a096':'#d0cec7'} stroke-width={road.highway?21:16}/><path d={`M${a.x} ${a.y}L${b.x} ${b.y}`} stroke={win.overlay==='traffic'&&road.delay?(road.delay>5?'#e25442':'#f4b842'):win.overlay==='transit'&&road.transit?'#9872c1':win.mode==='satellite'?'#c0b9a9':'#fff'} stroke-width={road.highway?15:11}/>{#if a.x!==b.x}<text x={(a.x+b.x)/2} y={a.y-13} text-anchor="middle" class="road-label">{win.overlay==='transit'&&road.transit?road.line:road.name}</text>{/if}{/each}
          {#if route}<polyline points={route.nodeIds.map(id=>{const p=nodes.get(id);return `${p.x},${p.y}`;}).join(' ')} fill="none" stroke="#fff" stroke-width="15"/><polyline points={route.nodeIds.map(id=>{const p=nodes.get(id);return `${p.x},${p.y}`;}).join(' ')} fill="none" stroke="#087ced" stroke-width="9"/>{/if}
          {#each mapsState.places as place}<g role="button" tabindex="0" aria-label={place.name} data-place={place.id} onclick={()=>command('select',{placeId:place.id})} onkeydown={e=>{if(e.key==='Enter'||e.key===' ')command('select',{placeId:place.id});}}><circle cx={place.x} cy={place.y} r={win.selectedId===place.id?14:10} fill={place.category==='park'?'#619a54':place.category==='station'?'#5086b9':'#df5553'} stroke="#fff" stroke-width="3"/><text x={place.x+15} y={place.y-15} class="place-label">{place.name}</text></g>{/each}
          <circle cx={mapsState.location.x} cy={mapsState.location.y} r="23" fill="#1c83ea" opacity=".15"/><circle cx={mapsState.location.x} cy={mapsState.location.y} r="8" fill="#1685f3" stroke="#fff" stroke-width="3"/>
        </svg>
        <div class="map-options"><select data-maps-control="map-mode" aria-label="Map type" value={win.mode} onchange={e=>command('mode',{mode:e.currentTarget.value})}><option value="map">Map</option><option value="satellite">Satellite · terrain</option></select><select data-maps-control="overlay" aria-label="Map overlay" value={win.overlay} onchange={e=>command('overlay',{overlay:e.currentTarget.value})}><option value="none">No overlay</option><option value="traffic">Local traffic</option><option value="transit">Local transit</option></select></div>
        <div class="zoom-controls"><button data-maps-control="zoom-in" aria-label="Zoom in" disabled={win.zoom>=8} onclick={()=>command('zoom',{zoom:Math.min(8,win.zoom+.5)})}>+</button><button data-maps-control="zoom-out" aria-label="Zoom out" disabled={win.zoom<=1} onclick={()=>command('zoom',{zoom:Math.max(1,win.zoom-.5)})}>−</button></div>
        {#if selected&&win.panel!=='directions'}<section class="place-card" aria-label="Place card"><button class="card-close" aria-label="Close place card" onclick={()=>command('select',{placeId:null})}>×</button><span class="category">{selected.category}</span><h2>{selected.name}</h2><p>{selected.address}</p><p>{selected.description}</p><button data-maps-control="place-directions" onclick={()=>command('directions',{fromId:'current-location',toId:selected.id,transport:win.transport})}>Directions</button><button data-maps-control="place-favorite" onclick={()=>command('favorite.set',{placeId:selected.id,enabled:!mapsState.favorites.includes(selected.id)})}>{mapsState.favorites.includes(selected.id)?'Remove Favorite':'Add Favorite'}</button>{#if selected.user}<button onclick={()=>command('pin.remove',{placeId:selected.id})}>Remove Pin</button>{/if}<button onclick={()=>command('share')}>Share…</button></section>{/if}
        <div class="scale">{mapDistance(1000/win.zoom,mapsState.preferences.distance)}<span></span></div><div class="attribution">Harbor · authored local map{win.mode==='satellite'?' · illustrative terrain, not photography':''}</div>
      </div>
    </div>
    {#if error}<div class="error" role="alert">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
  {:else}<p>Maps session unavailable.</p>{/if}
</section>

<style>
